import { useCallback, useEffect, useMemo, useState } from 'react';
import { MODE_CARD_TYPE, MODE_SOURCE, type ModeId } from '@lexpad/core';
import { gradeCard } from '@/db/mutations.js';
import { localTimeZone } from '@/lib/format.js';
import { practiceEnded, syncPractice } from '@/sync/store.js';

/** One answer in a run, for the summary. */
export interface RunAnswer {
  wordId: string;
  headword: string;
  correct: boolean;
}

/** What a mode tells the run about one answer. */
export interface ModeAnswer {
  wordId: string;
  headword: string;
  correct: boolean;
  /** What was typed, for the server's log of a typed mode. */
  typed?: string;
  /** The wrong option picked, for confusion pairs. */
  pickedWordId?: string;
  /** From the question being shown to the answer. */
  latencyMs?: number;
}

/** A run of one mode: its answers and the way to record one. */
export interface ModeRun {
  answers: readonly RunAnswer[];
  /**
   * This run's identity: the session id the server logs, and the seed every
   * shuffle of the run is drawn from, so a round is the same round on every
   * render and Play again is a new one.
   */
  seed: string;
  record: (answer: ModeAnswer) => Promise<void>;
  /** Starts a new run (Play again): a new session id and no answers. */
  restart: () => void;
}

/**
 * Records a mode's answers through the same path as a session's cards:
 * `gradeCard` writes the optimistic copy and queues the review with the
 * mode's card type, its source (`game` for the games, `session` for the
 * drills) and the mode as the deck. The server judges: Match, Speed, Say it
 * and Use it in a sentence never move a schedule (spec §2.8, case 1);
 * Dictation, Builder and Collocations count like spelling and cloze, under
 * the notebook's extra-practice rule. Daily totals and the streak count
 * either way.
 *
 * A failed local write is not swallowed here: the mode shows what happened
 * on screen and the run keeps going.
 */
export function useModeRun(mode: ModeId): ModeRun {
  const [answers, setAnswers] = useState<RunAnswer[]>([]);
  const [seed, setSeed] = useState<string>(() => crypto.randomUUID());
  const timeZone = useMemo(() => localTimeZone(), []);

  // Answers go in batches while the mode runs, and the rest when it closes.
  useEffect(
    () => () => {
      void practiceEnded();
    },
    [],
  );

  const record = useCallback(
    async (answer: ModeAnswer): Promise<void> => {
      setAnswers((list) => [
        ...list,
        { wordId: answer.wordId, headword: answer.headword, correct: answer.correct },
      ]);
      await gradeCard(
        {
          wordId: answer.wordId,
          correct: answer.correct,
          cardType: MODE_CARD_TYPE[mode],
          source: MODE_SOURCE[mode],
          deck: mode,
          sessionId: seed,
          ...(answer.typed === undefined ? {} : { typed: answer.typed }),
          ...(answer.pickedWordId === undefined ? {} : { pickedWordId: answer.pickedWordId }),
          ...(answer.latencyMs === undefined ? {} : { latencyMs: answer.latencyMs }),
        },
        timeZone,
      );
      void syncPractice();
    },
    [mode, seed, timeZone],
  );

  const restart = useCallback(() => {
    setSeed(crypto.randomUUID());
    setAnswers([]);
  }, []);

  return { answers, seed, record, restart };
}

/** The words missed in a run, each once, in the order they were first missed. */
export function missedWords(answers: readonly RunAnswer[]): { wordId: string; headword: string }[] {
  const seen = new Set<string>();
  const out: { wordId: string; headword: string }[] = [];
  for (const answer of answers) {
    if (answer.correct || seen.has(answer.wordId)) continue;
    seen.add(answer.wordId);
    out.push({ wordId: answer.wordId, headword: answer.headword });
  }
  return out;
}
